import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long sum = 0, fact = 1;
            for (int i = 1; i <= n; i++) {
                fact *= i;
                sum += fact;
            }
            System.out.println(sum);
        }
    }
}

